const groupOwnedPrizes = uid => {const owned=redemptions.value.filter(r=>r.requesterId===uid&&r.status==='approved'),groups=new Map();for(const prize of owned){const group=groups.get(prize.title)||{...prize,id:prize.title,quantity:0,prizeIds:[]};group.quantity++;group.prizeIds.push(prize.id);groups.set(prize.title,group)}return [...groups.values()]}
