const historyRecords = computed(()=>{const uid=user.value?.uid;if(!uid)return[];const taskRecords=tasks.value.filter(t=>['done','review','rejected'].includes(t.status)&&(t.creatorId===uid||t.receiverId===uid)).map(t=>{const points=Number(t.roll??t.points??0),when=t.reviewedAt||t.completedAt||t.rejectedAt||t.createdAt;let detail,amount='';if(t.status==='review'){detail=t.receiverId===uid?'你已完成任務，等待發布者驗收。':'對方已完成任務，等待你驗收。';amount=t.receiverId===uid?`待 ${points} 點`:'待驗收'}else if(t.status==='done'){detail=t.receiverId===uid?'任務已驗收，點數已入帳。':'你已驗收對方的任務。';amount=t.receiverId===uid?`+ ${points} 點`:'已驗收'}else{detail=t.rejectReason?`任務遭駁回：${t.rejectReason}`:'任務已遭駁回。';amount='已退回'}return{id:'task-'+t.id,icon:'📝',title:t.title,detail,amount,status:t.status,statusLabel:t.status==='review'?'等待驗收':t.status==='done'?'已完成':'已駁回',when,kind:'task'}});const redemptionRecords=redemptions.value.filter(r=>r.requesterId===uid||r.approverId===uid).map(r=>{const requester=r.requesterId===uid,detail=r.status==='pending'?(requester?'等待另一半確認兌換，點數暫時保留。':'另一半申請兌換，等待你確認。'):r.status==='rejected'?(requester?'兌換遭拒，保留的點數已釋放。':'你已拒絕兌換。'):r.status==='use_pending'?(requester?'等待另一半確認使用獎品。':'另一半申請使用獎品，等待你確認。'):r.status==='used'?'獎品已確認使用。':requester?'兌換已確認，獎品在獎品區。':'你已確認兌換。',amount=r.status==='pending'&&requester?`待 ${r.points} 點`:r.status==='rejected'&&requester?`+ ${r.points} 點`:['approved','use_pending','used'].includes(r.status)&&requester?`− ${r.points} 點`:'',rStatus=r.status;return{id:'redeem-'+r.id,icon:r.emoji||'🎁',title:r.title,detail,amount,status:rStatus,statusLabel:rStatus==='pending'?'等待兌換確認':rStatus==='use_pending'?'等待使用確認':rStatus==='used'?'已兌換':rStatus==='approved'?'已確認兌換':'已拒絕',when:r.usedAt||r.useRequestedAt||r.reviewedAt||r.createdAt,kind:'redemption'}});return [...taskRecords,...redemptionRecords].sort((a,b)=>historyTime(b.when)-historyTime(a.when))})
