const todayCycle = () => { const date=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()); const hour=Number(new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Taipei',hour:'2-digit',hourCycle:'h23'}).format(new Date())); return date+'-'+(hour>=12?'pm':'am') }
const todayDate = () => new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())
const yesterdayDate = () => {const date=new Date();date.setDate(date.getDate()-1);return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(date)}
const taiwanDay = value => value ? new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(historyTime(value))) : ''
const dateParts = value => value.split('-').map(Number)
const dayNumber = value => {const [year,month,day]=dateParts(value);return Date.UTC(year,month-1,day)/86400000}
const nextAnnualDate = (month,day) => {const [currentYear]=dateParts(todayDate()),format=(year)=>`${year}-${String(month).padStart(2,'0')}-${String(month===2&&day===29&&new Date(Date.UTC(year,1,29)).getUTCMonth()!==1?28:day).padStart(2,'0')}`;let date=format(currentYear);if(dayNumber(date)<dayNumber(todayDate()))date=format(currentYear+1);return date}
const nextHolidaySolarDate = (month,day) => {const [year]=dateParts(todayDate()),today=dayNumber(todayDate());for(let offset=0;offset<=8;offset++){const targetYear=year+offset,date=`${targetYear}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`,parsed=new Date(Date.UTC(targetYear,month-1,day));if(parsed.getUTCMonth()!==month-1||parsed.getUTCDate()!==day)continue;if(dayNumber(date)>=today)return date}return ''}
const dateDistance = value => Math.max(0,dayNumber(value)-dayNumber(todayDate()))
const dateLabel = value => new Date(`${value}T00:00:00+08:00`).toLocaleDateString('zh-TW',{month:'long',day:'numeric',timeZone:'Asia/Taipei'})
const nextHolidayLunarDate = (month,day) => {try{const start=dayNumber(todayDate())*86400000,format=new Intl.DateTimeFormat('en-US-u-ca-chinese',{month:'numeric',day:'numeric',timeZone:'Asia/Taipei'});for(let offset=0;offset<=400;offset++){const date=new Date(start+offset*86400000),parts=format.formatToParts(date),lunarMonth=parts.find(p=>p.type==='month')?.value,lunarDay=parts.find(p=>p.type==='day')?.value;if(lunarMonth===String(month)&&lunarDay===String(day))return `${date.getUTCFullYear()}-${String(date.getUTCMonth()+1).padStart(2,'0')}-${String(date.getUTCDate()).padStart(2,'0')}`}return ''}catch{return ''}}
const holidayNextDate = holiday => holiday.calendar==='lunar'?nextHolidayLunarDate(holiday.month,holiday.day):nextHolidaySolarDate(holiday.month,holiday.day)
const holidayIcon = holiday => holidaySeeds.find(seed=>seed.id===holiday.id)?.emoji||'🎉'
const holidayCalendarLabel = holiday => `${holiday.calendar==='lunar'?'農曆':'國曆'} ${holiday.month} 月 ${holiday.day} 日`
const relationshipDays = computed(()=>{clock.value;if(!coupleDates.value.togetherDate||dayNumber(todayDate())<dayNumber(coupleDates.value.togetherDate))return null;return dayNumber(todayDate())-dayNumber(coupleDates.value.togetherDate)+1})
const datedHolidayItems = computed(()=>{clock.value;return holidayItems.value.map(holiday=>{const date=holidayNextDate(holiday);return {...holiday,date,days:date?dateDistance(date):Infinity,emoji:holidayIcon(holiday)}}).sort((a,b)=>a.days-b.days||a.name.localeCompare(b.name,'zh-TW'))})
const selectedHolidayItems = computed(()=>datedHolidayItems.value.filter(holiday=>holiday.selected))
const holidayDates = computed(()=>selectedHolidayItems.value.filter(holiday=>holiday.date&&Number.isFinite(holiday.days)))
