const importantDates = computed(()=>{clock.value;const personal=[];if(coupleDates.value.togetherDate){const [,month,day]=dateParts(coupleDates.value.togetherDate);personal.push({date:nextAnnualDate(month,day),name:'在一起紀念日',emoji:'💗'})}if(coupleDates.value.myBirthday){const [,month,day]=dateParts(coupleDates.value.myBirthday);personal.push({date:nextAnnualDate(month,day),name:'我的生日',emoji:'🎂'})}if(coupleDates.value.partnerBirthday){const [,month,day]=dateParts(coupleDates.value.partnerBirthday);personal.push({date:nextAnnualDate(month,day),name:(partner.value?.name||'另一半')+'的生日',emoji:'🎂'})}return [...holidayDates.value,...personal.map(e=>({...e,days:dateDistance(e.date)}))].sort((a,b)=>a.days-b.days).slice(0,4)})
const expired = t => t.kind==='每日固定' ? t.cycle!==todayCycle() : t.kind==='限期任務' && t.due && todayDate()>t.due
const publishedTaskState = task => task.kind==='每日固定'&&task.rootId===task.id?(tasks.value.find(instance=>instance.rootId===task.id&&instance.cycle===todayCycle())?.status||'open'):task.status
const publishedTaskStatusLabel = task => {const status=publishedTaskState(task);return status==='review'?'對方已完成・待我驗收':status==='done'?'已驗收完成':status==='rejected'?'已駁回・等待對方重做':'等待對方完成'}
const taskScheduleDate = task => task.kind==='每日固定'?String(task.cycle||'').slice(0,10):task.kind==='限期任務'&&task.due?task.due:taiwanDay(task.createdAt)
const yesterdayTasks=computed(()=>{clock.value;return tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&taskScheduleDate(t)===yesterdayDate())})
const yesterdayTaskIds = computed(()=>new Set(yesterdayTasks.value.map(task=>task.id)))
const shown = computed(()=>{clock.value;return section.value==='我的任務'?tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&!expired(t)&&!yesterdayTaskIds.value.has(t.id)):section.value==='驗收任務'?tasks.value.filter(t=>t.status==='review'&&t.creatorId===user.value?.uid):tasks.value.filter(t=>t.creatorId===user.value?.uid&&(t.kind==='每日固定'?t.rootId===t.id:!expired(t)))})
const myTaskCount = computed(()=>{clock.value;return tasks.value.filter(t=>['open','rejected'].includes(t.status)&&t.receiverId===user.value?.uid&&!expired(t)).length})
const myPublishedTaskCount = computed(()=>{clock.value;return tasks.value.filter(t=>t.creatorId===user.value?.uid&&(t.kind==='每日固定'?t.rootId===t.id:!expired(t))).length})
const reviewTaskCount = computed(()=>tasks.value.filter(t=>t.status==='review'&&t.creatorId===user.value?.uid).length)
const form=ref({email:'',password:'',nickname:''}), authMode=ref('login'), error=ref(''), taskForm=ref({title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5}), invite=ref(''), activeInviteCode=ref(''), rejectReason=ref(''), notice=ref('')
const dateSaveMessage=ref(''), dateSaving=ref(false), dateSaveError=ref(false)
const showHolidaySettings=ref(false), holidayPickerOpen=ref(false), holidayPickerSelection=ref({}), holidayPickerQuery=ref(''), holidayPickerMessage=ref(''), holidayFormOpen=ref(false), holidaySaving=ref(false), holidayMessage=ref(''), holidayMessageError=ref(false), holidayEditorId=ref(''), holidayForm=ref({name:'',calendar:'solar',month:'',day:''}), holidayDeleteId=ref(''), restoreHolidaysPrompt=ref(false)
const nicknameDraft=ref(''), nicknameDirty=ref(false), nicknameMessage=ref(''), nicknameSaving=ref(false), nicknameError=ref(false)
const showNicknameEditor=ref(false), showDateEditor=ref(false)
const rewardForm=ref({title:'',points:10,emoji:'🎁'}), editingRewardId=ref('')
const redeemingRewardId=ref('')
const reviewingRedemptionId=ref(''), redemptionReviewError=ref({id:'',message:''})
const publishedTaskLimit=ref(5), showEndedPublishedTasks=ref(false), showYesterdayTasks=ref(false)
const taskGroupsForDisplay=computed(()=>{
  if(section.value==='我的任務')return [{key:'today',label:'今日任務',tasks:shown.value,collapsible:false,expanded:true},{key:'yesterday',label:'昨日未完成',tasks:yesterdayTasks.value,collapsible:true,expanded:showYesterdayTasks.value}]
  if(section.value==='發布任務'){
    const isDailyRoot=task=>task.kind==='每日固定'&&task.rootId===task.id
    const active=shown.value.filter(task=>isDailyRoot(task)||!['done','rejected'].includes(task.status))
    const ended=shown.value.filter(task=>!isDailyRoot(task)&&['done','rejected'].includes(task.status))
    return [{key:'active',label:'待處理',tasks:active,collapsible:false,expanded:true},{key:'ended',label:'已結束',tasks:ended,collapsible:true,expanded:showEndedPublishedTasks.value}]
  }
  return [{key:'all',label:'',tasks:shown.value,collapsible:false,expanded:true}]
})
watch(section,()=>{publishedTaskLimit.value=5;showEndedPublishedTasks.value=false;showYesterdayTasks.value=false})
