function say(s){notice.value=s;setTimeout(()=>notice.value='',3500)}
async function ensureDailyTasks(){const pairId=profile.value?.pairId;if(!pairId||!user.value)return;const cycle=todayCycle();for(const t of tasks.value){if(t.kind==='每日固定'&&t.rootId===t.id&&t.cycle!==cycle&&!tasks.value.some(x=>x.rootId===t.id&&x.cycle===cycle)){try{const instanceRef=doc(db,'pairs',pairId,'tasks',t.id+'-'+cycle);await setDoc(instanceRef,{title:t.title,note:t.note,kind:t.kind,due:null,cycle,rootId:t.id,rewardType:t.rewardType,points:t.points,status:'open',pairId,creatorId:t.creatorId,receiverId:t.receiverId,createdAt:serverTimestamp()})}catch{}}}}
function syncCoupleDates(){const birthdays=savedCoupleDateData.value.birthdays||{},otherId=otherUserId.value||partner.value?.id;coupleDates.value={togetherDate:savedCoupleDateData.value.togetherDate||'',myBirthday:user.value?birthdays[user.value.uid]||'':'',partnerBirthday:otherId?birthdays[otherId]||'':''}}
const holidayDocData = (seed,uid) => ({name:seed.name,calendar:seed.calendar,month:seed.month,day:seed.day,selected:true,isDefault:true,updatedBy:uid,updatedAt:serverTimestamp(),createdAt:serverTimestamp()})
async function ensureHolidaySettings(pairId,uid){const stateRef=doc(db,'pairs',pairId,'settings','holidays');await runTransaction(db,async tx=>{const state=await tx.get(stateRef);if(state.exists())return;tx.set(stateRef,{initialized:true,updatedBy:uid,updatedAt:serverTimestamp()});holidaySeeds.forEach(seed=>tx.set(doc(db,'pairs',pairId,'holidays',seed.id),holidayDocData(seed,uid)))})}
function stopLive(){[stopTasks,stopProfile,stopPartner,stopPair,stopRewards,stopRedemptions,stopDates,stopHolidays].forEach(fn=>fn?.());stopTasks=stopProfile=stopPartner=stopPair=stopRewards=stopRedemptions=stopDates=stopHolidays=null}
watch(()=>{clock.value;return todayCycle()},()=>ensureDailyTasks())
onMounted(()=>{refreshTimer=setInterval(()=>clock.value=Date.now(),30000);stops.push(onAuthStateChanged(auth,async u=>{stopLive();user.value=u;profile.value=null;partner.value=null;otherUserId.value='';savedCoupleDateData.value={};coupleDates.value={togetherDate:'',myBirthday:'',partnerBirthday:''};holidayItems.value=holidaySeeds.map(seed=>({...seed,selected:true,isDefault:true}));holidaysReady.value=false;holidayError.value='';nicknameDraft.value=u?.displayName||'';nicknameDirty.value=false;nicknameMessage.value='';tasks.value=[];redemptions.value=[];rewards.value=[...starterRewards];if(!u)return
  stopProfile=onSnapshot(doc(db,'users',u.uid),async snap=>{if(!snap.exists()){await setDoc(doc(db,'users',u.uid),{name:u.displayName||u.email,points:0,pointsBalance:0,pairId:null,partnerId:null,createdAt:serverTimestamp()},{merge:true});return}
    profile.value={id:snap.id,...snap.data()};if(!nicknameDirty.value)nicknameDraft.value=profile.value.name||u.displayName||''
    const pairId=profile.value.pairId
    if(pairId){if(!stopTasks)stopTasks=onSnapshot(collection(db,'pairs',pairId,'tasks'),s=>{tasks.value=s.docs.map(d=>({id:d.id,...d.data()}));ensureDailyTasks()})
