      if(!stopRedemptions)stopRedemptions=onSnapshot(collection(db,'pairs',pairId,'redemptions'),s=>{redemptions.value=s.docs.map(d=>({id:d.id,...d.data()}))})
      if(!stopPair)stopPair=onSnapshot(doc(db,'pairs',pairId),s=>{if(!s.exists())return;const p=s.data(),other=p.ownerId===u.uid?p.partnerId:p.ownerId;otherUserId.value=other||'';syncCoupleDates();if(other){if(!stopPartner)stopPartner=onSnapshot(doc(db,'users',other),q=>{partner.value=q.exists()?{id:q.id,...q.data()}:null;syncCoupleDates()});if(!stopHolidays)stopHolidays=onSnapshot(collection(db,'pairs',pairId,'holidays'),q=>{holidayItems.value=q.docs.map(d=>({id:d.id,...d.data()}));holidayError.value='';holidaysReady.value=true},e=>{holidayError.value=e.code==='permission-denied'?'讀取節日失敗：請在 Firebase 發布最新版 Firestore 規則。':'讀取節日失敗：'+e.message;holidaysReady.value=false});ensureHolidaySettings(pairId,u.uid).catch(e=>{holidayError.value=e.code==='permission-denied'?'初始化節日失敗：請在 Firebase 發布最新版 Firestore 規則。':'初始化節日失敗：'+e.message;holidaysReady.value=false})}else{stopHolidays?.();stopHolidays=null;holidayItems.value=holidaySeeds.map(seed=>({...seed,selected:true,isDefault:true}));holidaysReady.value=false}})
      if(!stopDates)stopDates=onSnapshot(doc(db,'pairs',pairId,'settings','dates'),s=>{savedCoupleDateData.value=s.exists()?s.data():{};syncCoupleDates()})}
    else {stopTasks?.();stopRewards?.();stopRedemptions?.();stopPartner?.();stopDates?.();stopHolidays?.();stopTasks=stopRewards=stopRedemptions=stopPartner=stopDates=stopHolidays=null;tasks.value=[];redemptions.value=[];rewards.value=[...starterRewards];savedCoupleDateData.value={};coupleDates.value={togetherDate:'',myBirthday:'',partnerBirthday:''};holidayItems.value=holidaySeeds.map(seed=>({...seed,selected:true,isDefault:true}));holidaysReady.value=false}
  })
}))})
