function openTaskEditor(task){if(task.status!=='open'||task.creatorId!==user.value?.uid)return say('只有尚未完成的任務可以修改。');editingTaskId.value=task.id;editingTaskRootId.value=task.kind==='每日固定'&&task.rootId===task.id?task.id:'';taskForm.value={title:task.title,note:task.note||'',kind:task.kind,due:task.due||'',rewardType:task.rewardType||'fixed',points:task.points??5};show.value='publish'}
