async function removeTask(task){if(!profile.value?.pairId||!user.value)return say('請先登入並完成配對。');if(task.status!=='open'||task.creatorId!==user.value.uid)return say('只有尚未完成的任務可以刪除。');if(!window.confirm(`確定要刪除「${task.title}」嗎？`))return;try{const related=task.kind==='每日固定'&&task.rootId===task.id?tasks.value.filter(t=>t.id===task.id||(t.rootId===task.id&&t.status==='open')):[task];for(let offset=0;offset<related.length;offset+=400){const batch=writeBatch(db);related.slice(offset,offset+400).forEach(item=>batch.delete(doc(db,'pairs',profile.value.pairId,'tasks',item.id)));await batch.commit()}say('任務已刪除。')}catch(e){say(e.code==='permission-denied'?'刪除失敗：只有發布者能刪除尚未完成的任務。':'刪除任務失敗：'+e.message)}}
async function requestRedemption(reward){
  const pairId=profile.value?.pairId
  if(!pairId||!user.value||!partner.value)return say('請先登入並完成配對。')
  if(redeemingRewardId.value)return
  redeemingRewardId.value=reward.id
  try{
    const rewardRef=doc(db,'pairs',pairId,'rewards',reward.id)
    const redemptionsRef=collection(db,'pairs',pairId,'redemptions')
    const redemptionRef=doc(redemptionsRef)
    const accountRef=doc(db,'users',user.value.uid)
    const [taskList,redemptionList]=await Promise.all([
      getDocs(collection(db,'pairs',pairId,'tasks')),
      getDocs(redemptionsRef)
    ])
    await runTransaction(db,async tx=>{
      const reads=await Promise.all([
        tx.get(rewardRef),tx.get(accountRef),
        ...taskList.docs.map(item=>tx.get(item.ref)),
        ...redemptionList.docs.map(item=>tx.get(item.ref))
      ])
      const giftSnap=reads[0],accountSnap=reads[1]
      const taskSnaps=reads.slice(2,2+taskList.size)
      const redemptionSnaps=reads.slice(2+taskList.size)
      if(!giftSnap.exists())throw Error('這份禮物已被移除，請重新整理。')
      const uid=user.value.uid
      const earned=Number(accountSnap.data()?.pointsBalance||0)+taskSnaps.filter(item=>item.exists()&&item.data().status==='done'&&item.data().receiverId===uid&&!item.data().pointsCredited).reduce((sum,item)=>sum+Number(item.data().roll??item.data().points??0),0)
      const reserved=redemptionSnaps.filter(item=>item.exists()&&item.data().requesterId===uid&&(item.data().status==='pending'||(item.data().status==='approved'&&!item.data().pointsDebited))).reduce((sum,item)=>sum+Number(item.data().points||0),0)
      if(earned-reserved<giftSnap.data().points)throw Error('可用點數不足。')
      tx.set(redemptionRef,{pairId,rewardId:reward.id,title:giftSnap.data().title,emoji:giftSnap.data().emoji,points:giftSnap.data().points,requesterId:uid,approverId:partner.value.id,status:'pending',createdAt:serverTimestamp()})
    })
    say('兌換申請已送出，等待另一半確認。')
  }catch(e){say(e.code==='permission-denied'?'兌換失敗：請確認 Firebase 已發布最新 Firestore 規則。':'兌換失敗：'+e.message)}
  finally{redeemingRewardId.value=''}
}
async function reviewRedemption(redemption,approve){reviewingRedemptionId.value=redemption.id;redemptionReviewError.value={id:'',message:''};try{const redemptionRef=doc(db,'pairs',profile.value.pairId,'redemptions',redemption.id),accountRef=doc(db,'users',redemption.requesterId);await runTransaction(db,async tx=>{const [snapshot,accountSnap]=await Promise.all([tx.get(redemptionRef),tx.get(accountRef)]);if(!snapshot.exists()||snapshot.data().status!=='pending')throw Error('這筆兌換已經處理過，請重新整理。');tx.update(redemptionRef,{status:approve?'approved':'rejected',reviewedAt:serverTimestamp(),...(approve?{pointsDebited:true}:{})});if(approve){const balance=Number(accountSnap.data()?.pointsBalance||0);tx.update(accountRef,{pointsBalance:balance-Number(snapshot.data().points||0),pointsEventRedemptionId:redemption.id})}});say(approve?'已確認兌換，點數已扣除。':'已拒絕兌換，點數已退回。')}catch(e){const message=e.code==='permission-denied'?'Firebase 拒絕了確認交易，請管理者發布最新版 firestore.rules。':'確認失敗：'+e.message;redemptionReviewError.value={id:redemption.id,message};say(message)}finally{reviewingRedemptionId.value=''}}
async function requestPrizeUse(group){const prizeId=group.prizeIds?.[0];if(!prizeId)return;try{await updateDoc(doc(db,'pairs',profile.value.pairId,'redemptions',prizeId),{status:'use_pending',useRequestedAt:serverTimestamp()});say('已申請使用一份「'+group.title+'」，等待另一半確認。')}catch(e){say('申請使用失敗：'+e.message)}}
async function reviewPrizeUse(prize,approve){try{await runTransaction(db,async tx=>{const prizeRef=doc(db,'pairs',profile.value.pairId,'redemptions',prize.id),snapshot=await tx.get(prizeRef);if(!snapshot.exists()||snapshot.data().status!=='use_pending'||snapshot.data().approverId!==user.value?.uid)throw Error('這筆使用申請已處理。');tx.update(prizeRef,approve?{status:'used',usedAt:serverTimestamp()}:{status:'approved',useRejectedAt:serverTimestamp()})});say(approve?'已確認使用，獎品移到已兌換。':'已拒絕使用，獎品回到對方的獎品。')}catch(e){say('處理使用申請失敗：'+e.message)}}
async function saveCoupleDates(){dateSaveMessage.value='';dateSaveError.value=false;const pairId=profile.value?.pairId,otherId=otherUserId.value||partner.value?.id;if(!user.value||!pairId||!otherId){dateSaveError.value=true;dateSaveMessage.value='請先登入並完成配對，再儲存重要日子。';return}dateSaving.value=true;try{await setDoc(doc(db,'pairs',pairId,'settings','dates'),{togetherDate:coupleDates.value.togetherDate||'',birthdays:{[user.value.uid]:coupleDates.value.myBirthday||'', [otherId]:coupleDates.value.partnerBirthday||''},updatedBy:user.value.uid,updatedAt:serverTimestamp()});dateSaveMessage.value='重要日子已儲存，首頁倒數已更新。'}catch(e){dateSaveError.value=true;dateSaveMessage.value=e.code==='permission-denied'?'儲存失敗：請在 Firebase 發布最新版 Firestore 規則。':'儲存重要日子失敗：'+e.message}finally{dateSaving.value=false}}
