function validHolidayDate(calendar,month,day){if(!Number.isInteger(month)||!Number.isInteger(day)||month<1||month>12||day<1)return false;if(calendar==='lunar')return day<=30;const maxDay=new Date(Date.UTC(2000,month,0)).getUTCDate();return day<=maxDay}
