function openHolidayPicker(){if(!user.value||!profile.value?.pairId)return say('請先登入並完成配對，再挑選常見節日。');holidayPickerSelection.value=Object.fromEntries(holidayCatalog.map(item=>{const saved=holidayItems.value.find(h=>h.id===item.id||h.id===('catalog-'+item.id));return [item.id,!!saved?.selected]}));holidayPickerQuery.value='';holidayPickerMessage.value='';holidayPickerOpen.value=true}
