async function saveHolidayPicker(){const pairId=profile.value?.pairId,uid=user.value?.uid;if(!pairId||!uid)return;const chosen=holidayCatalog.filter(item=>holidayPickerSelection.value[item.id]),batch=writeBatch(db),now=serverTimestamp();let changes=0;for(const item of holidayCatalog){const saved=holidayItems.value.find(h=>h.id===item.id||h.id===('catalog-'+item.id)),selected=!!holidayPickerSelection.value[item.id];if(saved){if(!selected){batch.delete(doc(db,'pairs',pairId,'holidays',saved.id));changes++}else if(!saved.selected){batch.update(doc(db,'pairs',pairId,'holidays',saved.id),{selected:true,updatedBy:uid,updatedAt:now});changes++}}else if(selected){const conflict=holidayItems.value.find(h=>holidayNameKey(h.name)===holidayNameKey(item.name));if(conflict){holidayPickerMessage.value='所選節日名稱與現有項目重複，請先調整現有節日。';return}const id=holidaySeeds.some(seed=>seed.id===item.id)?item.id:'catalog-'+item.id;batch.set(doc(db,'pairs',pairId,'holidays',id),{...holidayDocData(item,uid),...(id.startsWith('catalog-')?{isDefault:false}:{})});changes++}}if(!changes){holidayPickerOpen.value=false;return}holidaySaving.value=true;holidayPickerMessage.value='';try{await batch.commit();holidayPickerOpen.value=false;say('已更新節日選擇（'+chosen.length+' 個首頁提醒）。')}catch(e){holidayPickerMessage.value=e.code==='permission-denied'?'儲存失敗：請在 Firebase 發布最新版 Firestore 規則。':'儲存節日選擇失敗：'+e.message}finally{holidaySaving.value=false}}
async function saveHoliday(){holidayMessage.value='';holidayMessageError.value=false;const pairId=profile.value?.pairId,name=holidayForm.value.name.trim(),calendar=holidayForm.value.calendar,month=Number(holidayForm.value.month),day=Number(holidayForm.value.day);if(!user.value||!pairId)return say('請先登入並完成配對，再管理常見節日。');if(!name)return holidayMessageError.value=true,holidayMessage.value='請輸入節日名稱。';if(holidayMessageError.value)return;if(name.length>40)return holidayMessageError.value=true,holidayMessage.value='名稱請控制在 40 個字以內。';if(!validHolidayDate(calendar,month,day))return holidayMessageError.value=true,holidayMessage.value=calendar==='lunar'?'請輸入有效的農曆月份與日期（1–12 月、1–30 日）。':'請輸入有效的國曆日期。';const normalizedName=holidayNameKey(name),duplicate=holidayItems.value.some(item=>holidayNameKey(item.name)===normalizedName&&item.id!==holidayEditorId.value),reservedDefaultName=holidaySeeds.some(seed=>holidayNameKey(seed.name)===normalizedName&&seed.id!==holidayEditorId.value);if(duplicate||reservedDefaultName)return holidayMessageError.value=true,holidayMessage.value='已有同名節日，請改用其他名稱。';holidaySaving.value=true;try{const data={name,calendar,month,day,updatedBy:user.value.uid,updatedAt:serverTimestamp()},editing=holidayItems.value.find(item=>item.id===holidayEditorId.value);if(editing?.isDefault){await updateDoc(doc(db,'pairs',pairId,'holidays',editing.id),data)}else{const targetId=customHolidayId(name),targetRef=doc(db,'pairs',pairId,'holidays',targetId);await runTransaction(db,async tx=>{const target=await tx.get(targetRef);if(target.exists()&&targetId!==editing?.id)throw Error('已有同名節日，請改用其他名稱。');if(editing){const currentRef=doc(db,'pairs',pairId,'holidays',editing.id),current=targetId===editing.id?target:await tx.get(currentRef);if(!current.exists())throw Error('節日資料已更新，請重新整理後再試。');const existing=current.data();if(targetId===editing.id)tx.update(targetRef,data);else{tx.set(targetRef,{...data,selected:existing.selected,isDefault:false,createdAt:existing.createdAt||serverTimestamp()});tx.delete(currentRef)}}else tx.set(targetRef,{...data,selected:true,isDefault:false,createdAt:serverTimestamp()})})}holidayFormOpen.value=false;say(editing?'節日已更新。':'節日已新增並加入首頁倒數。')}catch(e){holidayMessageError.value=true;holidayMessage.value=e.code==='permission-denied'?'儲存失敗：請在 Firebase 發布最新版 Firestore 規則。':e.message==='已有同名節日，請改用其他名稱。'||e.message==='節日資料已更新，請重新整理後再試。'?e.message:'儲存節日失敗：'+e.message}finally{holidaySaving.value=false}}
