async function restoreDefaultHolidays(){const pairId=profile.value?.pairId,uid=user.value?.uid;if(!pairId||!uid)return;const restoredNames=new Set(holidaySeeds.map(seed=>holidayNameKey(seed.name))),conflict=holidayItems.value.find(item=>!item.isDefault&&restoredNames.has(holidayNameKey(item.name)));if(conflict){holidayError.value=`自訂節日「${conflict.name}」與內建名稱重複，請先修改或刪除後再還原。`;return}holidaySaving.value=true;holidayError.value='';try{const batch=writeBatch(db),stateRef=doc(db,'pairs',pairId,'settings','holidays');batch.set(stateRef,{initialized:true,updatedBy:uid,updatedAt:serverTimestamp()});holidaySeeds.forEach(seed=>batch.set(doc(db,'pairs',pairId,'holidays',seed.id),holidayDocData(seed,uid)));await batch.commit();restoreHolidaysPrompt.value=false;say('內建節日已還原；自訂節日保留。')}catch(e){holidayError.value=e.code==='permission-denied'?'還原失敗：請在 Firebase 發布最新版 Firestore 規則。':'還原節日失敗：'+e.message}finally{holidaySaving.value=false}}
function markNicknameDirty(){nicknameDirty.value=true;nicknameMessage.value=''}
async function saveNickname(){nicknameMessage.value='';nicknameError.value=false;if(!user.value){nicknameError.value=true;nicknameMessage.value='請先登入再設定暱稱。';return}const nickname=nicknameDraft.value.trim();if(!nickname){nicknameError.value=true;nicknameMessage.value='請輸入暱稱。';return}if(nickname.length>30){nicknameError.value=true;nicknameMessage.value='暱稱請控制在 30 個字以內。';return}nicknameSaving.value=true;try{await updateDoc(doc(db,'users',user.value.uid),{name:nickname});profile.value={...profile.value,name:nickname};nicknameDirty.value=false;try{await updateProfile(user.value,{displayName:nickname});nicknameMessage.value='暱稱已儲存，另一半也會看到更新。'}catch{nicknameError.value=true;nicknameMessage.value='網站暱稱已更新；登入資料同步失敗，請稍後再試。'}}catch(e){nicknameError.value=true;nicknameMessage.value=e.code==='permission-denied'?'儲存失敗：請確認 Firebase 已發布允許更新暱稱的規則。':'儲存暱稱失敗：'+e.message}finally{nicknameSaving.value=false}}
async function joinPair(){const code=invite.value.trim().toUpperCase();if(!user.value)return say('請先登入再輸入邀請碼。');if(!/^[A-Z0-9]{5}$/.test(code))return say('請輸入五碼大寫英文與數字邀請碼。');try{await runTransaction(db,async tx=>{const pairRef=doc(db,'pairs',code),memberRef=doc(db,'users',user.value.uid),[p,member]=await Promise.all([tx.get(pairRef),tx.get(memberRef)]);if(!p.exists()||p.data().partnerId||p.data().ownerId===user.value.uid||!p.data().expiresAt||p.data().expiresAt.toMillis()<=Date.now())throw Error('邀請碼無效、已使用或已過期。');if(member.exists()&&member.data().pairId)throw Error('這個帳號已經有邀請或完成配對，請先取消目前邀請。');tx.update(pairRef,{partnerId:user.value.uid});if(member.exists())tx.update(memberRef,{pairId:code,partnerId:p.data().ownerId});else tx.set(memberRef,{name:user.value.displayName||user.value.email,points:0,pointsBalance:0,pairId:code,partnerId:p.data().ownerId,createdAt:serverTimestamp()})});invite.value='';show.value='';say('配對成功！你們連線了')}catch(e){say(e.code==='permission-denied'?'配對被 Firestore 規則拒絕。請確認已發布最新版 firestore.rules。':e.message)}}
async function publish(){if(!taskForm.value.title.trim())return say('請先輸入任務名稱。');if(taskForm.value.kind==='限期任務'&&!taskForm.value.due)return say('請選擇任務到期日。');const receiverId=otherUserId.value||partner.value?.id||profile.value?.partnerId;if(!profile.value?.pairId||!receiverId)return say('請先登入並邀請另一半配對。');try{const title=taskForm.value.title.trim(),note=taskForm.value.note.trim(),due=taskForm.value.kind==='限期任務'?taskForm.value.due:null,rewardType=taskForm.value.rewardType,points=rewardType==='fixed'?Number(taskForm.value.points):null;if(editingTaskId.value){const task=tasks.value.find(t=>t.id===editingTaskId.value);if(!task||task.creatorId!==user.value.uid||task.status!=='open')throw Error('任務已完成或狀態已改變，請重新整理後再試。');const update={title,note,due,rewardType,points},targets=editingTaskRootId.value?tasks.value.filter(t=>t.id===editingTaskRootId.value||(t.rootId===editingTaskRootId.value&&t.status==='open'&&!expired(t))):[task],batch=writeBatch(db);targets.forEach(t=>batch.update(doc(db,'pairs',profile.value.pairId,'tasks',t.id),update));await batch.commit();say('任務已修改。')}else{const taskRef=doc(collection(db,'pairs',profile.value.pairId,'tasks')),data={title,note,kind:taskForm.value.kind,due,cycle:taskForm.value.kind==='每日固定'?todayCycle():null,rootId:taskForm.value.kind==='每日固定'?taskRef.id:null,rewardType,points,status:'open',pairId:profile.value.pairId,creatorId:user.value.uid,receiverId,createdAt:serverTimestamp()};await setDoc(taskRef,data);section.value='發布任務';say('任務已發布。')}editingTaskId.value='';editingTaskRootId.value='';taskForm.value={title:'',note:'',kind:'臨時發布',due:'',rewardType:'fixed',points:5};show.value=''}catch(e){say(e.code==='permission-denied'?'儲存失敗：請確認 Firebase 已發布允許修改任務的最新版規則。':e.message.startsWith('任務')?e.message:'任務儲存失敗：'+e.message)}}
async function complete(t,allowExpired=false){try{if(t.status==='rejected'){await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'open',rejectReason:'',acknowledgedAt:serverTimestamp()});return}
  if(expired(t)&&!allowExpired)return say('這個任務已經過期。')
  const roll=t.rewardType==='random'?Math.floor(Math.random()*11):Number(t.points||5)
   await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'review',roll,completedAt:serverTimestamp()});t.roll=roll;show.value='dice';setTimeout(()=>show.value='',1800)
}catch(e){say('更新失敗：'+e.message)}}
async function review(t,ok){try{if(ok){const taskRef=doc(db,'pairs',profile.value.pairId,'tasks',t.id),accountRef=doc(db,'users',t.receiverId);await runTransaction(db,async tx=>{const [taskSnap,accountSnap]=await Promise.all([tx.get(taskRef),tx.get(accountRef)]);if(!taskSnap.exists()||taskSnap.data().status!=='review')throw Error('這筆任務已處理過。');const data=taskSnap.data(),roll=Number(data.roll??data.points??0),balance=Number(accountSnap.data()?.pointsBalance||0);tx.update(taskRef,{status:'done',reviewedAt:serverTimestamp(),pointsCredited:true});tx.update(accountRef,{pointsBalance:balance+roll,pointsEventTaskId:t.id})});say('已驗收並送出 '+Number(t.roll??t.points)+' 點。')}else{if(!rejectReason.value.trim())return say('請先填寫駁回原因。');await updateDoc(doc(db,'pairs',profile.value.pairId,'tasks',t.id),{status:'rejected',rejectReason:rejectReason.value.trim(),rejectedAt:serverTimestamp()});rejectReason.value='';say('任務已退回。')}show.value=''}catch(e){say('驗收失敗：'+e.message)}}
</script>

<template>
<div class="app"><div class="random-background" :style="{backgroundImage:'url('+backgroundImage+')'}"></div><header><div class="brand"><img :src="cloudCatImage" alt="" class="cloud-cat-mark"><div><b>貓崽的窩</b><small>our little home</small></div></div><div class="tagline">♥　把喜歡藏進每天的小事裡　♥</div><button v-if="!partner" class="invite mobile-invite" @click="show='pair'">💌 邀請另一半</button><button class="login" @click="user?signOut(auth):show='login'">{{user?'登出 '+name:'登入 / 註冊'}}</button></header>
<main><aside class="side"><div class="couple"><span class="face">{{name.slice(0,1)}}</span><span class="face pink">♡</span><div><b>{{profile?.pairId?name+' & '+(partner?.name||'另一半'):'我們的小宇宙'}}</b><small>{{profile?.pairId?'兩顆心，住在同一個小窩裡':'登入後邀請另一半加入'}}</small></div></div><div class="caption">OUR LITTLE SPACE</div><button v-for="([icon,t]) in tabs" :key="t" :class="{selected:page===t}" @click="page=t"><img class="navicon-img" :src="icon" :alt="t"><span><b>{{t}}</b><i v-if="t==='任務'&&hasTaskAttention||t==='獎品'&&hasPrizeAttention" class="attention-dot" aria-label="有待處理項目"></i><small>{{t==='任務'?'一起完成小事':t==='獎品'?'收藏喜歡的禮物':t==='兌換'?'讓點數變成驚喜':t==='紀錄'?'一路走來的回憶':t==='設定'?'管理重要日期與節日':'我們的日常'}}</small></span></button><div class="quote">you are my<br>favorite person. <small>— every little day</small></div></aside>
<section class="content"><div class="eyebrow">✦　OUR LITTLE SPACE</div><h1>{{title}} <img :src="cloudCatImage" alt="" class="cloud-cat-inline"></h1><p class="sub">每一個小小任務，都是偷偷說喜歡的方式。</p>
<template v-if="page==='首頁'"><div class="hero"><div><small>✦ OUR LITTLE ROUTINE ✦</small><h2>喜歡，不只說說而已。<br><em>我們把它做成日常。</em></h2><p>一杯記得的飲料、一句晚安，還有好多為彼此用心的小事。</p><button class="primary" @click="page='任務';openTaskPublisher()">發布一個小任務　＋</button></div><div class="pup center-pup"><img class="center-pup-icon" :src="homepageIcon" alt="首頁角色圖"><img :src="cloudCatImage" alt="" class="cloud-cat-bubble"></div></div><div class="metrics"><button @click="page='任務';section='我的任務'"><small>我的任務</small><b>{{myTaskCount}} 件</b><i>查看收到的任務　›</i></button><button @click="page='任務';section='發布任務'"><small>我發布的任務</small><b>{{myPublishedTaskCount}} 件</b><i>管理發布內容　›</i></button><button @click="page='任務';section='驗收任務'"><small>等待驗收</small><b>{{reviewTaskCount}} 件</b><i>確認對方完成的任務　›</i></button><button @click="page='獎品';prizeSection='獎品'"><small>我的專屬點數</small><b>{{points}} pt</b><i>對方有 {{partnerPoints}} 點　›</i></button></div><section class="important-days"><div class="days-header"><div><small>OUR LITTLE CALENDAR</small><h2>接下來的重要日子</h2></div><button @click="page='設定'">設定日期　›</button></div><div v-if="relationshipDays!==null" class="together-counter">我們已經一起 <strong>{{relationshipDays}}</strong> 天<span v-if="importantDates.some(d=>d.name==='在一起紀念日')">・下個週年還有 {{importantDates.find(d=>d.name==='在一起紀念日')?.days}} 天</span></div><div class="important-date-list"><article v-for="d in importantDates" :key="d.name" class="important-date-item"><span>{{d.emoji}}</span><b>{{d.name}}</b><small>{{dateLabel(d.date)}}・<span class="countdown-days">{{d.days===0?'就是今天':`還有 ${d.days} 天`}}</span></small></article></div></section><div class="note">「最喜歡的日常，是每一件事都有你。」 <small>一張貓咪捎來的小紙條　♡</small></div></template>
<template v-else-if="page==='任務'"><div class="bar"><div class="seg"><button v-for="s in ['我的任務','發布任務','驗收任務']" :key="s" :class="{on:section===s}" @click="section=s">{{s}}</button></div><button class="primary" @click="openTaskPublisher">＋ 發布新任務</button></div><p v-if="user&&!profile?.pairId" class="empty">先邀請另一半加入你們的小宇宙。</p><template v-for="group in taskGroupsForDisplay" :key="group.key"><section v-if="group.tasks.length" class="published-task-group"><div v-if="group.label" class="published-task-group-heading"><h2 v-if="!group.collapsible">{{group.label}} <span>{{group.tasks.length}}</span></h2><button v-else type="button" :aria-expanded="group.expanded" @click="group.key==='yesterday'?showYesterdayTasks=!showYesterdayTasks:showEndedPublishedTasks=!showEndedPublishedTasks">{{group.label}} <span>{{group.tasks.length}}</span><b>{{group.expanded?'收起':'展開'}}</b></button></div><template v-if="!group.collapsible||group.expanded"><article v-for="(t,i) in group.tasks.slice(0,publishedTaskLimit)" :key="t.id" :class="['task',t.kind==='臨時發布'?'task-temporary':t.kind==='每日固定'?'task-daily':'task-deadline']"><div class="number">{{String(i+1).padStart(2,'0')}}<hr>♡</div><div class="tasktext"><small class="task-kind" :class="{'task-kind-temporary':t.kind==='臨時發布','task-kind-daily':t.kind==='每日固定','task-kind-deadline':t.kind==='限期任務'}">{{t.kind}}</small><span class="task-kind-note">　·　小小的心意</span><h3>{{t.title}} <i v-if="taskNeedsAttention(t)" class="attention-dot" aria-label="需要你處理"></i></h3><small v-if="section==='發布任務'||t.status==='review'||t.status==='rejected'" class="published-task-status" :class="'status-'+publishedTaskState(t)">{{publishedTaskStatusLabel(t)}}</small><p>{{t.note||'一件小小的心意，等你完成。'}}</p><div v-if="section==='發布任務'&&t.creatorId===user?.uid&&t.status==='open'" class="task-actions"><button class="task-edit" @click="openTaskEditor(t)">修改</button><button class="task-delete" @click="removeTask(t)">刪除</button></div></div><div class="reward"><b>{{t.roll??t.points}}</b><small>POINTS</small></div><button v-if="t.status==='review'&&t.creatorId===user?.uid" class="complete" @click="show='review'">驗收任務</button><button v-else-if="t.receiverId===user?.uid" class="complete" @click="complete(t,group.key==='yesterday')">{{t.status==='rejected'?'我知道了':'✓ 我完成了'}}</button></article><button v-if="group.tasks.length>publishedTaskLimit" class="show-more-tasks" type="button" @click="publishedTaskLimit+=5">顯示更多（還有 {{group.tasks.length-publishedTaskLimit}} 筆）</button></template></section></template><div v-if="!taskGroupsForDisplay.some(group=>group.tasks.length)" class="empty"><img :src="cloudCatImage" alt="" class="cloud-cat-empty"><h3>這裡還空空的呢</h3><p>配對後發布小任務，讓今天多一件期待。</p></div></template>
<template v-else-if="page==='獎品'">
  <div class="bar"><div class="seg"><button v-for="tab in ['獎品','對方的獎品','待確認','已兌換']" :key="tab" :class="{on:prizeSection===tab}" @click="prizeSection=tab">{{tab}}<i v-if="tab==='待確認'&&hasPrizeAttention" class="attention-dot" aria-label="有待確認獎品"></i></button></div></div>
  <template v-if="prizeSection==='獎品'"><div class="points"><small>MY PRIZES</small><b>{{myPrizes.reduce((sum,item)=>sum+item.quantity,0)}}<i> 件獎品</i></b><p>另一半已確認，隨時可以申請使用。</p></div><section class="redemption-panel"><h3>我的獎品</h3><article v-for="r in myPrizes" :key="r.title" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}} <span class="prize-quantity">× {{r.quantity}}</span></b><small>持有 {{r.quantity}} 份</small></div><button @click="requestPrizeUse(r)">申請使用 1 份</button></article><p v-if="!myPrizes.length" class="empty">還沒有獎品，去兌換一份喜歡的禮物吧。</p></section></template>
  <template v-else-if="prizeSection==='對方的獎品'"><div class="points"><small>PARTNER'S PRIZES</small><b>{{partnerPrizes.reduce((sum,item)=>sum+item.quantity,0)}}<i> 件獎品</i></b><p>只能查看另一半目前持有的獎品。</p></div><section class="redemption-panel"><h3>{{partner?.name||'另一半'}}的獎品</h3><article v-for="r in partnerPrizes" :key="r.title" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}} <span class="prize-quantity">× {{r.quantity}}</span></b><small>持有 {{r.quantity}} 份</small></div></article><p v-if="!partnerPrizes.length" class="empty">另一半目前還沒有獎品。</p></section></template>
  <template v-else-if="prizeSection==='待確認'"><section class="redemption-panel"><h3>等待我確認</h3><article v-for="r in prizesToReview" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small :class="r.status==='pending'?'pending-redeem':'pending-use'">{{r.status==='pending'?'兌換申請・確認後扣 '+r.points+' 點':'使用申請・確認後移到已兌換'}}</small></div><button :disabled="!!reviewingRedemptionId" @click="r.status==='pending'?reviewRedemption(r,true):reviewPrizeUse(r,true)">{{reviewingRedemptionId===r.id?'處理中…':'確認'}}</button><button class="redeem-reject" :disabled="!!reviewingRedemptionId" @click="r.status==='pending'?reviewRedemption(r,false):reviewPrizeUse(r,false)">拒絕</button><small v-if="redemptionReviewError.id===r.id" class="redemption-error" role="alert">{{redemptionReviewError.message}}</small></article><p v-if="!prizesToReview.length" class="empty">目前沒有需要你確認的獎品。</p></section><section class="redemption-panel"><h3>等待對方確認</h3><article v-for="r in pendingPrizes.filter(item=>item.requesterId===user?.uid)" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small :class="r.status==='pending'?'pending-redeem':'pending-use'">{{r.status==='pending'?'兌換申請・等待對方確認':'使用申請・等待對方確認'}}</small></div></article><p v-if="!pendingPrizes.some(r=>r.requesterId===user?.uid)" class="empty">沒有等待對方確認的申請。</p></section></template>
  <section v-else class="redemption-panel"><h3>已兌換</h3><article v-for="r in usedPrizes" :key="r.id" class="redemption-item"><span class="redemption-emoji">{{r.emoji}}</span><div class="redemption-info"><b>{{r.title}}</b><small>已確認使用・{{formatHistoryTime(r.usedAt)}}</small></div></article><p v-if="!usedPrizes.length" class="empty">目前沒有已兌換獎品。</p></section>
</template>
<template v-else-if="page==='紀錄'"><div class="history-list"><article v-for="record in visibleHistoryRecords" :key="record.id" class="history-record"><span>{{record.icon}}</span><div><b>{{record.title}}</b><span class="history-status" :data-status="record.status">{{record.statusLabel}}</span><small>{{record.detail}}</small><time v-if="record.when">{{formatHistoryTime(record.when)}}</time></div><strong>{{record.amount}}</strong></article><div v-if="!historyRecords.length" class="empty"><h3>還沒有活動紀錄</h3><p>完成任務或兌換禮物後，紀錄會顯示在這裡。</p></div><button v-if="historyRecords.length>historyVisibleLimit" class="show-more-tasks history-load-more" type="button" @click="historyVisibleLimit+=5">顯示更多紀錄（還有 {{historyRecords.length-historyVisibleLimit}} 筆）</button></div></template><template v-else-if="page==='兌換'"><div class="bar reward-bar"><div><small>OUR LITTLE TREATS</small><h2>把喜歡換成小驚喜</h2></div><button class="primary" @click="openRewardEditor()">＋ 新增禮物</button></div><div class="redeem-balance"><div><small>我的可用點數</small><strong>{{points}} <span>點</span></strong></div><p><span v-if="reservedPoints">待確認保留 {{reservedPoints}} 點<br></span>另一半確認兌換後才正式扣點。</p></div><div class="rewards"><article v-for="r in rewards" :key="r.id"><div class="rewardart">{{r.emoji}}</div><h3>{{r.title}}</h3><small>✦ {{r.points}} 點</small><div class="reward-actions"><button class="redeem-button" :disabled="!user||!profile?.pairId||points<r.points||!!redeemingRewardId" @click="requestRedemption(r)">{{redeemingRewardId===r.id?'送出中…':points<r.points?'點數不足':'兌換'}}</button><button class="reward-edit" @click="openRewardEditor(r)">修改</button><button class="reward-delete" @click="removeReward(r)">刪除</button></div></article></div><div v-if="!rewards.length" class="empty">🎁<h3>還沒有禮物</h3><p>新增一份小驚喜，讓點數有期待。</p></div></template><template v-else><section class="nickname-settings"><div class="settings-heading"><div><h2>個人暱稱</h2><p>目前暱稱：{{name}}</p></div><button class="settings-toggle" type="button" :aria-expanded="showNicknameEditor" @click="showNicknameEditor=!showNicknameEditor">{{showNicknameEditor?'收起':'修改暱稱'}}</button></div><p v-if="showNicknameEditor">修改後會同步更新你們空間裡顯示的名稱。</p><form v-if="showNicknameEditor" class="nickname-form" @submit.prevent="saveNickname"><label>你的暱稱<input v-model="nicknameDraft" @input="markNicknameDirty" maxlength="30" placeholder="輸入暱稱" :disabled="!user" required></label><button class="primary" type="submit" :disabled="!user||nicknameSaving">儲存暱稱</button><p v-if="nicknameMessage" class="nickname-message" :class="{error:nicknameError}">{{nicknameMessage}}</p><p v-else-if="!user" class="form-hint">請先登入後設定暱稱。</p></form></section><section class="date-settings"><div class="settings-heading"><div><h2>重要日期</h2><p>設定在一起的日子與雙方生日</p></div><button class="settings-toggle" type="button" :aria-expanded="showDateEditor" @click="showDateEditor=!showDateEditor">{{showDateEditor?'收起':'修改重要日期'}}</button></div><p v-if="showDateEditor">重要日期只包含在一起紀念日與生日，常見節日可在下方獨立管理。</p><form v-if="showDateEditor" class="date-form" @submit.prevent="saveCoupleDates"><label>在一起的日子<input v-model="coupleDates.togetherDate" type="date"></label><label>{{name}}的生日<input v-model="coupleDates.myBirthday" type="date"></label><label>{{partner?.name||'另一半'}}的生日<input v-model="coupleDates.partnerBirthday" type="date"></label><button class="primary wide" type="submit" :disabled="dateSaving||!user||!profile?.pairId||!otherUserId">{{dateSaving?'儲存中…':'儲存重要日子'}}</button><p v-if="dateSaveMessage" class="date-save-message" :class="{error:dateSaveError}">{{dateSaveMessage}}</p><p v-if="!user" class="form-hint">請登入並完成配對後儲存重要日子。</p><p v-else-if="!profile?.pairId||!otherUserId" class="form-hint">先邀請另一半加入並完成配對，重要日期才會同步保存。</p></form></section><section class="holiday-settings"><div class="settings-heading"><div><h2>常見節日</h2><p>勾選要在首頁提醒的節日，變更會同步給另一半。</p></div><div class="holiday-toolbar"><button class="settings-toggle" type="button" :disabled="!user||!profile?.pairId||!otherUserId||!holidaysReady||holidaySaving" @click="openHolidayPicker()">＋ 選擇常見節日</button><button class="holiday-custom-button" type="button" :disabled="!user||!profile?.pairId||!otherUserId||!holidaysReady||holidaySaving" @click="openHolidayEditor()">新增自訂節日</button><button class="holiday-restore-button" type="button" :disabled="!user||!profile?.pairId||!otherUserId||!holidaysReady||holidaySaving" @click="restoreHolidaysPrompt=!restoreHolidaysPrompt">還原內建節日</button></div></div><button class="holiday-collapse-toggle" type="button" aria-controls="holiday-content" :aria-expanded="showHolidaySettings" @click="showHolidaySettings=!showHolidaySettings">{{showHolidaySettings?'收起節日':'展開節日'}}</button><div v-if="showHolidaySettings" id="holiday-content"><p v-if="!user" class="holiday-hint">登入並完成配對後，就能一起管理節日。</p><p v-else-if="!otherUserId" class="holiday-hint">完成配對後，節日清單會由兩人共用。</p><p v-if="holidayError" class="holiday-feedback error" role="alert">{{holidayError}}</p><div v-if="restoreHolidaysPrompt" class="holiday-confirm" role="alert"><span>還原內建節日的原始名稱與日期，並重新勾選？自訂節日會保留。</span><button type="button" :disabled="holidaySaving" @click="restoreDefaultHolidays">確認還原</button><button type="button" @click="restoreHolidaysPrompt=false">取消</button></div><form v-if="holidayFormOpen" class="holiday-form" @submit.prevent="saveHoliday"><h3>{{holidayEditorId?'修改節日':'新增節日'}}</h3><label>節日名稱<input v-model="holidayForm.name" maxlength="40" placeholder="例如：相識紀念日" required></label><label>使用曆法<select v-model="holidayForm.calendar"><option value="solar">國曆</option><option value="lunar">農曆（不含閏月）</option></select></label><div class="holiday-date-fields"><label>月份<input v-model="holidayForm.month" type="number" min="1" max="12" inputmode="numeric" required></label><label>日期<input v-model="holidayForm.day" type="number" min="1" :max="holidayFormDayMax" inputmode="numeric" required></label></div><p class="holiday-hint">每年自動沿用；2 月 29 日只在閏年顯示。</p><p v-if="holidayMessage" class="holiday-feedback" :class="{error:holidayMessageError}" :role="holidayMessageError?'alert':'status'">{{holidayMessage}}</p><div class="holiday-form-actions"><button class="primary" type="submit" :disabled="holidaySaving">{{holidaySaving?'儲存中…':'儲存節日'}}</button><button class="settings-toggle" type="button" @click="holidayFormOpen=false">取消</button></div></form><div class="holiday-list"><article v-for="d in selectedHolidayItems" :key="d.id" class="holiday-item" :class="{'holiday-item-disabled':!d.selected}"><span class="holiday-emoji holiday-selected-emoji" aria-hidden="true">{{d.emoji}}</span><div class="holiday-detail"><b>{{d.name}} <small v-if="d.isDefault" class="holiday-default-label">內建</small></b><small>{{holidayCalendarLabel(d)}}<template v-if="d.date">・下次 {{dateLabel(d.date)}}</template><template v-else>・該日期暫無對應日</template></small></div><div class="holiday-actions"><template v-if="holidayDeleteId===d.id"><span class="holiday-delete-prompt">確定刪除？</span><button type="button" class="holiday-delete-confirm" :disabled="holidaySaving" @click="deleteHoliday(d)">刪除</button><button type="button" @click="holidayDeleteId=''">取消</button></template><template v-else><button type="button" :disabled="!user||!profile?.pairId||!otherUserId||!holidaysReady||holidaySaving" @click="openHolidayEditor(d)">修改</button><button type="button" class="holiday-delete-button" :disabled="!user||!profile?.pairId||!otherUserId||!holidaysReady||holidaySaving" @click="holidayDeleteId=d.id">刪除</button></template></div></article><p v-if="holidaysReady&&!selectedHolidayItems.length" class="holiday-empty">節日清單還是空的，新增幾個想記得的日子吧。</p></div></div><div v-if="holidayPickerOpen" class="holiday-picker-backdrop" role="presentation" @click.self="holidayPickerOpen=false"><section class="holiday-picker-dialog" role="dialog" aria-modal="true" aria-labelledby="holiday-picker-title"><header class="holiday-picker-header"><div><small>CHOOSE YOUR HOLIDAYS</small><h2 id="holiday-picker-title">挑選要提醒的節日</h2><p>選取的節日會加入共用清單並顯示在首頁。</p></div><button type="button" class="holiday-picker-close" aria-label="關閉節日選擇器" @click="holidayPickerOpen=false">×</button></header><label class="holiday-picker-search">搜尋節日<input v-model="holidayPickerQuery" type="search" placeholder="輸入節日名稱"></label><div class="holiday-picker-list"><label v-for="item in filteredHolidayCatalog" :key="item.id" class="holiday-picker-option"><input type="checkbox" :checked="!!holidayPickerSelection[item.id]" :disabled="holidaySaving" @change="setHolidayPickerItem(item,$event)"><span class="holiday-picker-emoji">{{item.emoji}}</span><span class="holiday-picker-name"><b>{{item.name}}</b><small>{{holidayCalendarLabel(item)}}・{{item.month}} 月 {{item.day}} 日</small></span><span class="holiday-picker-added">{{holidayPickerSelection[item.id]?'已選':'未選'}}</span></label><p v-if="!filteredHolidayCatalog.length" class="holiday-picker-empty">找不到符合的節日。</p></div><p v-if="holidayPickerMessage" class="holiday-feedback error" role="alert">{{holidayPickerMessage}}</p><footer class="holiday-picker-footer"><span>已選 {{selectedHolidayCatalogCount}} 個節日</span><button type="button" class="primary" :disabled="holidaySaving" @click="saveHolidayPicker">{{holidaySaving?'儲存中…':'儲存節日選擇'}}</button></footer></section></div></section></template>
</section><aside class="right"><small>OUR LITTLE JOURNAL</small><div class="calendar">OUR DAY<strong>{{new Date().toLocaleDateString('zh-TW',{day:'2-digit',timeZone:'Asia/Taipei'})}}</strong>{{new Date().toLocaleDateString('zh-TW',{weekday:'long',timeZone:'Asia/Taipei'})}}</div><div class="thought">TODAY'S LITTLE THOUGHT<p>有你一起，<br>普通的日子<br>也亮亮的。</p>— from kitty <img :src="cloudCatImage" alt="" class="cloud-cat-thought"></div><div class="pup sidepup"><img class="side-pup-icon" :src="sidebarIcon" alt="側邊角色圖"></div><button v-if="!partner" class="invite" @click="show='pair'">💌　邀請另一半</button></aside></main>
<nav class="mobile-nav" :class="{paired:!!partner}"><button v-for="([icon,t]) in tabs" :key="t" :class="{selected:page===t}" @click="page=t"><img class="mobile-icon" :src="icon" :alt="t">{{t}}<i v-if="t==='任務'&&hasTaskAttention||t==='獎品'&&hasPrizeAttention" class="attention-dot" aria-label="有待處理項目"></i></button><button v-if="!partner" class="mobile-invite-nav" title="邀請另一半" @click="show='pair'"><span>💌</span>邀請</button></nav>
<div v-if="notice" class="toast-pop" role="status" aria-live="polite">{{notice}}</div><div v-if="show" class="overlay" @pointerdown.self="show=''"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><button class="close" aria-label="關閉視窗" @click="show=''">×</button><div class="dialog-icon"><img v-if="show==='login'" :src="cloudCatImage" alt="" class="cloud-cat-dialog"><span v-else>{{show==='dice'?'🎲':show==='pair'?'💌':show==='review'?'✨':show==='reward'?'🎁':'📝'}}</span></div><small>YOUR LITTLE HOME</small><h2 id="dialog-title">{{show==='login'?'回到你們的小宇宙':show==='pair'?'邀請另一半一起來':show==='review'?'任務完成驗收':show==='dice'?'任務完成！':show==='reward'?(editingRewardId?'修改禮物':'新增禮物'):show==='publish'?(editingTaskId?'修改任務':'發布一個小任務'):'發布一個小任務'}}</h2>
<template v-if="show==='login'"><form @submit.prevent="authSubmit"><input v-if="authMode==='signup'" v-model="form.nickname" placeholder="暱稱" required><input v-model="form.email" type="email" placeholder="Email" autocomplete="email" required><input v-model="form.password" type="password" placeholder="密碼（至少 6 個字元）" minlength="6" required><p v-if="error" class="auth-error">{{error}}</p><button class="primary wide" :disabled="authBusy">{{authBusy?'請稍候…':authMode==='signup'?'建立帳號':'登入'}}</button></form><button class="auth-switch login-switch" @click="authMode=authMode==='login'?'signup':'login'">{{authMode==='login'?'還沒有帳號？註冊':'已有帳號？返回登入'}}</button></template>
<template v-else-if="show==='pair'"><p>邀請碼為五碼大寫英文與數字，建立後 7 天有效，配對後立即失效。</p><div v-if="user&&profile?.pairId&&!partner" class="invite-code-box"><strong>{{activeInviteCode||profile.pairId}}</strong><button class="copy-invite" @click="copyInvite(activeInviteCode||profile.pairId)">複製</button></div><button v-if="user&&profile?.pairId&&!partner" class="auth-switch" @click="cancelInvite">取消目前邀請，改輸入另一半的邀請碼</button><button v-if="user&&!profile?.pairId" class="primary wide" @click="makeInvite">建立五碼邀請碼</button><input v-if="user&&!profile?.pairId" v-model="invite" maxlength="5" placeholder="輸入另一半的五碼邀請碼"><button v-if="user&&!profile?.pairId" class="primary wide" @click="joinPair">使用邀請碼配對</button><p v-if="!user">請先登入。</p><p v-if="partner">你們已經配對成功</p></template>
<template v-else-if="show==='reward'"><form @submit.prevent="saveReward"><label>禮物名稱<input v-model="rewardForm.title" maxlength="60" placeholder="例如：一起看電影" required></label><label>所需點數<input v-model.number="rewardForm.points" type="number" min="0" max="9999" step="1" required></label><label>禮物圖示<input v-model="rewardForm.emoji" maxlength="8" placeholder="🎁"></label><button class="primary wide" type="submit">{{editingRewardId?'儲存修改':'新增禮物'}}</button></form></template>
<template v-else-if="show==='publish'"><form @submit.prevent="publish"><label>任務名稱<input v-model="taskForm.title" maxlength="80" placeholder="例如：幫我買草莓牛奶" required></label><label>給對方的小紙條<textarea v-model="taskForm.note" maxlength="200" placeholder="補充小細節或偷偷撒個嬌…"></textarea></label><label>發布方式<select v-model="taskForm.kind" :disabled="!!editingTaskId"><option value="臨時發布">臨時發布</option><option value="每日固定">每天固定（台灣時間 12:00 刷新）</option><option value="限期任務">有期限，到期日隔日 00:00 過期</option></select></label><label v-if="taskForm.kind==='限期任務'">到期日<input v-model="taskForm.due" type="date" :min="todayDate()" required></label><div class="award-options"><span>完成獎勵</span><label><input v-model="taskForm.rewardType" type="radio" value="fixed"> 固定點數</label><label><input v-model="taskForm.rewardType" type="radio" value="random"> 完成時抽 0–10 點 🎲</label></div><label v-if="taskForm.rewardType==='fixed'">獎勵點數<input v-model.number="taskForm.points" type="number" min="0" max="999" required></label><p v-else class="form-hint">接收方按下「我完成了」時會擲骰子，驗收後才收到點數。</p><button class="primary wide" type="submit">{{editingTaskId?'儲存修改':'發布給另一半'}}</button></form></template>
<template v-else-if="show==='review'"><p>任務「{{tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)?.title}}」已完成。確認後點數會送給對方。</p><button class="primary wide" @click="tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)&&review(tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid),true)">✓ 驗收並送出點數</button><textarea v-model="rejectReason" placeholder="駁回原因（對方會看到）"></textarea><button class="auth-switch" @click="tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid)&&review(tasks.find(t=>t.status==='review'&&t.creatorId===user?.uid),false)">駁回並退回任務</button></template>
<template v-else><div class="die">🎲 <b>{{tasks.find(t=>t.status==='review'&&t.receiverId===user?.uid)?.roll??'✦'}}</b> pt</div><p>已送出驗收，等待發布者確認。</p></template></section></div>
</div>
</template>
